import React, { useState, useEffect } from 'react';
import { ClassKit } from '../types';
import { UPSELL_CHECKOUT_URL } from '../constants';

interface UpsellPopupProps {
  selectedKit: ClassKit;
  onReject: () => void;
}

const UpsellPopup: React.FC<UpsellPopupProps> = ({ selectedKit, onReject }) => {
  const [timeLeft, setTimeLeft] = useState(120); // 2 minutes

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleAccept = () => {
    window.location.href = UPSELL_CHECKOUT_URL;
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md"></div>

      {/* Modal Content */}
      <div className="relative w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl overflow-hidden animate-scaleUp">
        <div className="bg-orange-600 p-4 text-center">
          <span className="text-white font-black text-sm uppercase tracking-widest">
            ⚠️ OFERTA EXCLUSIVA: ESTA OPORTUNIDADE EXPIRA EM {formatTime(timeLeft)}
          </span>
        </div>

        <div className="p-8 md:p-12 text-center">
          <div className="inline-block bg-yellow-100 text-yellow-800 px-4 py-1 rounded-full font-black text-xs uppercase mb-4">
            ESPERE! NÃO VÁ AINDA!
          </div>

          <h2 className="text-3xl md:text-4xl font-black text-gray-900 mb-6 leading-tight uppercase tracking-tighter">
            Leve o PACOTE COMPLETO (6 Classes) por um preço ainda menor!
          </h2>

          <p className="text-gray-600 text-lg mb-8">
            Você está prestes a levar apenas a <span className="font-bold text-gray-800">{selectedKit.name}</span>. 
            Por apenas mais <span className="font-bold text-green-600">R$ 14,00</span>, você garante o acesso vitalício a todas as 6 classes agora mesmo.
          </p>

          <div className="bg-gray-50 rounded-3xl p-6 mb-8 border-2 border-dashed border-gray-200">
            <div className="flex flex-col items-center">
              <span className="text-gray-400 line-through text-sm">De R$ 65,40</span>
              <div className="flex items-center gap-2">
                <span className="text-gray-500 font-bold">POR APENAS</span>
                <span className="text-6xl font-black text-orange-600 tracking-tighter">R$ 24,90</span>
              </div>
              <span className="text-green-600 font-bold mt-2">ECONOMIA DE R$ 40,50 💰</span>
            </div>
          </div>

          <div className="flex flex-col gap-4">
            <button 
              onClick={handleAccept}
              className="w-full bg-orange-600 hover:bg-orange-500 text-white py-6 rounded-2xl font-black text-xl md:text-2xl transition-all transform hover:scale-105 shadow-xl uppercase flex flex-col items-center"
            >
              <span>Sim! Quero Tudo por R$ 24,90</span>
              <span className="text-xs opacity-80 font-normal normal-case mt-1">(Link Seguro do Checkout)</span>
            </button>

            <button 
              onClick={onReject}
              className="text-gray-400 hover:text-gray-600 font-bold text-sm underline transition-colors"
            >
              Não, obrigado. Quero pagar R$ {selectedKit.price} apenas pela {selectedKit.name}
            </button>
          </div>
        </div>

        {/* Features Minimal List */}
        <div className="bg-gray-50 p-6 flex justify-center gap-6 border-t border-gray-100">
          {['6 PDFs', 'Envio Imediato', 'Garantia'].map((f, i) => (
            <span key={i} className="text-[10px] font-black uppercase text-gray-400 flex items-center gap-1">
              <span className="text-green-500">✓</span> {f}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

