    { src: 'https://i.ibb.co/5WtZ0bTz/Imagens-da-Classe-de-Guia-2026.jpg', label: 'Amostra Classe de Guia' },
  ];

  const handleKitSelect = (kit: ClassKit) => {
    setUpsell({
      isOpen: true,
      selectedKit: kit
